using CrochetCraft.Data;using CrochetCraft.Models;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace CrochetCraft.Controllers;
public class AdminController(AppDbContext db):Controller {
 private bool IsAdmin()=>HttpContext.Session.GetString("Role")=="Admin"&&HttpContext.Session.GetInt32("UserId")!=null;
 private IActionResult Denied()=>RedirectToAction("Login","Account");
 public async Task<IActionResult> Index(){if(!IsAdmin())return Denied();ViewBag.Customers=await db.Users.CountAsync(x=>x.Role=="Customer");ViewBag.Revenue=await db.Orders.Where(x=>x.Status!="Cancelled").SumAsync(x=>(decimal?)x.Total)??0;ViewBag.LowStock=await db.Materials.CountAsync(x=>x.StockGrams<=x.ReorderLevel);return View(await db.Orders.Include(x=>x.User).Include(x=>x.Design).ThenInclude(x=>x!.Product).OrderByDescending(x=>x.Id).Take(8).ToListAsync());}
 public async Task<IActionResult> Products(){if(!IsAdmin())return Denied();return View(await db.Products.OrderByDescending(x=>x.Id).ToListAsync());}
 [HttpGet] public async Task<IActionResult> ProductForm(int? id){if(!IsAdmin())return Denied();return View(id==null?new Product():await db.Products.FindAsync(id)??new Product());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> ProductForm(Product item){if(!IsAdmin())return Denied();if(!ModelState.IsValid)return View(item);if(item.Id==0){db.Products.Add(item);}else{var old=await db.Products.FindAsync(item.Id);if(old==null)return NotFound();old.Name=item.Name;old.Category=item.Category;old.BasePrice=item.BasePrice;old.YarnGrams=item.YarnGrams;old.Description=item.Description;old.Emoji=item.Emoji;old.Active=item.Active;}await db.SaveChangesAsync();return RedirectToAction("Products");}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteProduct(int id){if(!IsAdmin())return Denied();var p=await db.Products.FindAsync(id);if(p!=null){p.Active=false;await db.SaveChangesAsync();}return RedirectToAction("Products");}
 public async Task<IActionResult> Orders(){if(!IsAdmin())return Denied();return View(await db.Orders.Include(x=>x.User).Include(x=>x.Design).ThenInclude(x=>x!.Product).OrderByDescending(x=>x.Id).ToListAsync());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> Status(int id,string status){if(!IsAdmin())return Denied();if(!new[]{"Pending","Making","Ready","Delivered","Cancelled"}.Contains(status))return BadRequest();var order=await db.Orders.FindAsync(id);if(order!=null){order.Status=status;await db.SaveChangesAsync();}return RedirectToAction("Orders");}
 public async Task<IActionResult> Materials(){if(!IsAdmin())return Denied();return View(await db.Materials.OrderBy(x=>x.Name).ToListAsync());}
 [HttpGet] public async Task<IActionResult> MaterialForm(int? id){if(!IsAdmin())return Denied();return View(id==null?new Material():await db.Materials.FindAsync(id)??new Material());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> MaterialForm(Material item){if(!IsAdmin())return Denied();if(!ModelState.IsValid)return View(item);if(item.Id==0)db.Materials.Add(item);else{var old=await db.Materials.FindAsync(item.Id);if(old==null)return NotFound();old.Name=item.Name;old.StockGrams=item.StockGrams;old.ReorderLevel=item.ReorderLevel;}await db.SaveChangesAsync();return RedirectToAction("Materials");}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteMaterial(int id){if(!IsAdmin())return Denied();var m=await db.Materials.FindAsync(id);if(m!=null){db.Materials.Remove(m);await db.SaveChangesAsync();}return RedirectToAction("Materials");}
}